import * as React from "react";
import { Box, Typography, Button, Card, CardContent } from "@mui/material";
import NavigationBar from "./NavigationBar";
import DateRangeIcon from "@mui/icons-material/DateRange";
import { useNavigate } from "react-router-dom";

import VenuesPage from "./VenuesPage";
import HairPage from "./HairPage";
import MakeupPage from "./MakeupPage";
import PhotographersPage from "./PhotographersPage";
import MusicPage from "./MusicPage";
import FloristPage from "./FloristPage";
import DresserPage from "./DresserPage";
import PlannerPage from "./PlannerPage";

export default function NewPage() {
  const [selectedDate, setSelectedDate] = React.useState(localStorage.getItem("selectedDate") || "Select a date");
  const [selectedPage, setSelectedPage] = React.useState("home");
  const navigate = useNavigate();

  const handleChangeDate = () => {
    navigate("/calendar"); // Navigate to the calendar page
  };

  // This handles the rendering of the content based on the selected page
  const renderContent = () => {
    switch (selectedPage) {
      case "venues":
        return <VenuesPage />;
      case "hair":
        return <HairPage />;
      case "makeup":
        return <MakeupPage />;
      case "photographers":
        return <PhotographersPage />;
      case "music":
        return <MusicPage />;
      case "florist":
        return <FloristPage />;
      case "dresser":
        return <DresserPage />;
      case "planner":
        return <PlannerPage />;
      default:
        return (
          <Box sx={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(250px, 1fr))", gap: 2 }}>
            {/* Define all pages and corresponding images here */}
            {[
              { title: "Venues", imageUrl: "/path/to/venue-image.jpg", page: "venues" },
              { title: "Hair", imageUrl: "/path/to/hair-image.jpg", page: "hair" },
              { title: "Makeup", imageUrl: "/path/to/makeup-image.jpg", page: "makeup" },
              { title: "Photographers", imageUrl: "/path/to/photographer-image.jpg", page: "photographers" },
              { title: "Music", imageUrl: "/path/to/music-image.jpg", page: "music" },
              { title: "Florist", imageUrl: "/path/to/florist-image.jpg", page: "florist" },
              { title: "Dresser", imageUrl: "/path/to/dresser-image.jpg", page: "dresser" },
              { title: "Planner", imageUrl: "/path/to/planner-image.jpg", page: "planner" }
            ].map((item, index) => (
              <Card
                key={index}
                sx={{
                  borderRadius: 6,
                  boxShadow: "0px 4px 10px rgba(0, 0, 0, 0.1)",
                  cursor: "pointer",
                  overflow: "hidden",
                  display: "flex",
                  flexDirection: "column",
                  backgroundColor: "transparent",
                }}
                onClick={() => setSelectedPage(item.page)}
              >
                <Box
                  sx={{
                    width: "100%",
                    height: 200,
                    backgroundImage: `url(${item.imageUrl})`,
                    backgroundSize: "cover",
                    backgroundPosition: "center",
                  }}
                />
                <CardContent sx={{ paddingTop: 2, backgroundColor: "#fff", textAlign: "center" }}>
                  <Typography variant="h6" sx={{ fontWeight: "bold" }}>
                    {item.title}
                  </Typography>
                </CardContent>
              </Card>
            ))}
          </Box>
        );
    }
  };

  return (
    <>
      <NavigationBar onSelect={setSelectedPage} />

      {/* Selected Date Display */}
      <Box sx={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        marginTop: 2,
        padding: 0,
        margin: 0,
        width: "100%", // Prevent overflow on the sides
        overflowX: "hidden"
      }}>
        <Typography variant="body1" fontWeight="bold">
          Selected Date: {selectedDate}
        </Typography>
        <Button
          startIcon={<DateRangeIcon />}
          sx={{ marginLeft: 1, textTransform: "capitalize" }}
          onClick={handleChangeDate}
        >
          Change
        </Button>
      </Box>

      {/* Dynamic Content */}
      <Box sx={{
        width: "100%",
        padding: 0,
        margin: 0,
        overflowX: "hidden", // Disable horizontal scrolling
        boxSizing: "border-box" // Ensure no overflow
      }}>
        {renderContent()}
      </Box>
    </>
  );
}
